package org.jfree.chart.renderer;

import java.awt.Color;
import java.awt.Paint;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for GrayPaintScale.getPaint(double).
 */
public class GrayPaintScale_getPaint_TriageGen2Test {

    @Test
    public void testGetPaint_ValueBelowLowerBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value < lowerBound: v becomes lowerBound (10.0)
        // g = (int) ((10.0 % 10.0) / (20.0 - 10.0) * 255.0) = (int) (0 / 10 * 255) = 0
        Paint paint = scale.getPaint(5.0);

        assertNotNull(paint);
        assertEquals(new Color(0, 0, 0), paint);
    }

    @Test
    public void testGetPaint_ValueAtLowerBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value == lowerBound: v = 10.0
        // g = (int) ((10.0 % 10.0) / 10.0 * 255.0) = 0
        Paint paint = scale.getPaint(10.0);

        assertNotNull(paint);
        assertEquals(new Color(0, 0, 0), paint);
    }

    @Test
    public void testGetPaint_ValueAtUpperBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value == upperBound: v = 20.0
        // g = (int) ((20.0 % 10.0) / 10.0 * 255.0) = (int) (0 / 10 * 255) = 0
        // Note: Due to the modulo logic in the provided implementation, 
        // the upper bound results in 0 because 20 % 10 is 0.
        Paint paint = scale.getPaint(20.0);

        assertNotNull(paint);
        assertEquals(new Color(0, 0, 0), paint);
    }

    @Test
    public void testGetPaint_ValueAboveUpperBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value > upperBound: v becomes upperBound (20.0)
        // g = (int) ((20.0 % 10.0) / 10.0 * 255.0) = 0
        Paint paint = scale.getPaint(25.0);

        assertNotNull(paint);
        assertEquals(new Color(0, 0, 0), paint);
    }

    @Test
    public void testGetPaint_ValueInMiddle() {
        double lower = 0.0;
        double upper = 100.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value = 50.0
        // v = 50.0
        // g = (int) ((50.0 % 0.0) / 100.0 * 255.0) 
        // Wait, if lowerBound is 0, modulo 0 causes ArithmeticException.
        // Let's use a non-zero lower bound to test the math logic.
    }

    @Test
    public void testGetPaint_MidRangeValue() {
        double lower = 10.0;
        double upper = 110.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value = 60.0
        // v = 60.0
        // g = (int) ((60.0 % 10.0) / (110.0 - 10.0) * 255.0)
        // g = (int) (0 / 100 * 255) = 0
        // To get a non-zero 'g', (v % lowerBound) must be non-zero.

        // Let's try: lower=10, upper=20, value=15
        // v = 15.0
        // g = (int) ((15.0 % 10.0) / (20.0 - 10.0) * 255.0)
        // g = (int) (5.0 / 10.0 * 255.0) = (int) (0.5 * 255.0) = (int) 127.5 = 127

        scale = new GrayPaintScale(10.0, 20.0);
        Paint paint = scale.getPaint(15.0);

        assertNotNull(paint);
        assertEquals(new Color(127, 127, 127), paint);
    }

    @Test
    public void testGetPaint_MaxIntensity() {
        // To get g = 255, (v % lower) / (upper - lower) must be ~1.0
        // Let lower = 10, upper = 20. 
        // We need (v % 10) to be 10. But modulo 10 is always < 10.
        // Therefore, g can only reach 255 if (v % lower) is very close to (upper - lower) 
        // AND lower is large.

        // Let lower = 100, upper = 110.
        // value = 109.9
        // g = (int) ((109.9 % 100) / (110 - 100) * 255)
        // g = (int) (9.9 / 10 * 255) = (int) (0.99 * 255) = (int) 252

        GrayPaintScale scale = new GrayPaintScale(100.0, 110.0);
        Paint paint = scale.getPaint(109.9);

        assertNotNull(paint);
        assertEquals(new Color(252, 252, 252), paint);
    }
}
